#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv)
{
    const char *input;
    char norm[1025];
    size_t norm_len = 0;
    size_t i;

    if (argc > 1)
        input = argv[1];
    else
        input = "";

    if (strlen(input) > 1024) {
        puts("TOO_LONG");
        return 0;
    }

    for (i = 0; input[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            if (isalpha(c))
                c = (unsigned char)toupper(c);
            norm[norm_len++] = (char)c;
        }
    }
    norm[norm_len] = '\0';

    int is_pal = 1;
    for (i = 0; i < norm_len / 2; ++i) {
        if (norm[i] != norm[norm_len - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
